import { test, expect } from '@playwright/test';

test.describe('Itemised Receipt After Checkout', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display an itemised receipt with correct details after successful checkout', async ({ page }) => {
    // Intercept the API call to get cart items
    await page.route('**/api/cart/items', (route) => {
      route.continue();
    });

    // Intercept the API call to get cart total
    await page.route('**/api/cart/total', (route) => {
      route.continue();
    });

    // Intercept the API call to get payment success
    await page.route('**/api/payment/success', (route) => {
      route.continue();
    });

    // Verify the cart items are listed
    const itemList = page.getByRole('region', { name: /cart items/i });
    await expect(itemList).toBeVisible();

    const item1 = page.getByRole('heading', { name: /Item 1/i });
    await expect(item1).toBeVisible();

    const item2 = page.getByRole('heading', { name: /Item 2/i });
    await expect(item2).toBeVisible();

    const item3 = page.getByRole('heading', { name: /Item 3/i });
    await expect(item3).toBeVisible();

    // Verify item details are displayed
    const item1Details = page.getByText(/Item 1 - $/i);
    await expect(item1Details).toBeVisible();

    const item2Details = page.getByText(/Item 2 - $/i);
    await expect(item2Details).toBeVisible();

    const item3Details = page.getByText(/Item 3 - $/i);
    await expect(item3Details).toBeVisible();

    // Verify total amount is displayed
    const total = page.getByText(/Total: $/i);
    await expect(total).toBeVisible();

    // Verify payment success message
    const successMessage = page.getByText(/Payment successful/i);
    await expect(successMessage).toBeVisible();

    // Verify receipt button is visible and clickable
    const receiptButton = page.getByRole('button', { name: /view receipt/i });
    await expect(receiptButton).toBeVisible();

    // Click the receipt button
    await receiptButton.click();

    // Verify receipt page is displayed
    const receiptPage = page.getByRole('region', { name: /receipt/i });
    await expect(receiptPage).toBeVisible();

    // Verify receipt details are displayed
    const receiptDetails = page.getByText(/Item 1 - $/i);
    await expect(receiptDetails).toBeVisible();

    const receiptDetails2 = page.getByText(/Item 2 - $/i);
    await expect(receiptDetails2).toBeVisible();

    const receiptDetails3 = page.getByText(/Item 3 - $/i);
    await expect(receiptDetails3).toBeVisible();

    // Verify total amount is displayed on receipt page
    const receiptTotal = page.getByText(/Total: $/i);
    await expect(receiptTotal).toBeVisible();

    // Verify receipt is formatted correctly
    const receiptTable = page.getByRole('region', { name: /receipt table/i });
    await expect(receiptTable).toBeVisible();

    // Verify discounts are displayed if applicable
    const discount = page.getByText(/Discount: $/i);
    await expect(discount).toBeVisible();
  });

